DATA = "diff --git a/skills/codex-delegate/scripts/relay.mjs b/skills/codex-delegate/scripts/relay.mjs\nindex 70372f8..54c6eb5 100644\n--- a/skills/codex-delegate/scripts/relay.mjs\n+++ b/skills/codex-delegate/scripts/relay.mjs\n@@ -164,12 +164,9 @@ function timestamp() {\n function buildArgv(opts, finalPath) {\n   const argv = [\"exec\"];\n   if (opts.resumeLast) argv.push(\"resume\", \"--last\");\n-  // ponytail: shell:true on win32 (needed for the codex.cmd shim) doesn't quote\n-  // args, so a temp path with spaces (C:\\Users\\First Last\\...) splits and the\n-  // trailing \"-\" misparses (issue #3). Quote the only spaceable arg in argv.\n-  // Ceiling: if quoting proves too blunt, drop shell:true and resolve the shim.\n-  const outPath = process.platform === \"win32\" ? `\"${finalPath}\"` : finalPath;\n-  argv.push(\"--json\", \"-o\", outPath);\n+  // Keep argv as argument values, not shell fragments. Windows quoting is\n+  // handled when constructing the command for the npm-installed codex.cmd shim.\n+  argv.push(\"--json\", \"-o\", finalPath);\n   // `-s`/`-C` are not accepted by `exec resume`; resume inherits the original\n   // session's sandbox and working root, and we set the child process cwd below.\n   if (!opts.resumeLast) {\n@@ -181,6 +178,23 @@ function buildArgv(opts, finalPath) {\n   return argv;\n }\n \n+// Windows npm installations expose codex through a .cmd shim, so cmd.exe must\n+// interpret the command. Quote each argument as a separate cmd token rather\n+// than embedding quotes in buildArgv's values. Double percent signs to avoid\n+// environment-variable expansion inside paths (including user profile names).\n+function quoteWindowsCmdArg(value) {\n+  const arg = String(value);\n+  if (!arg) return '\"\"';\n+  // cmd.exe treats quotes as delimiters and caret as an escape character.\n+  // CLI options and generated paths have no embedded quotes; reject those\n+  // rather than silently changing what Codex receives.\n+  if (arg.includes('\"') || /[\\r\\n]/.test(arg)) {\n+    throw new Error(\"unsupported quote or newline in Codex command argument\");\n+  }\n+  const escaped = arg.replace(/%/g, \"%%\");\n+  return /[\\s&|<>^()]/.test(escaped) ? `\"${escaped}\"` : escaped;\n+}\n+\n function extractThreadId(event) {\n   return (\n     event.thread_id ??\n@@ -253,10 +267,17 @@ function reportUnavailable(writeResult, resultPath) {\n \n function dispatchToCodex(opts, brief, run, writeResult) {\n   const argv = buildArgv(opts, run.finalPath);\n-  // shell:true on Windows so the codex.cmd shim resolves (see codexVersion). Safe:\n-  // the brief is fed via child.stdin below — never argv — and argv holds only\n-  // sandbox enums, model names, and file paths, with no shell metacharacters.\n-  const child = spawn(\"codex\", argv, { cwd: opts.cd, stdio: [\"pipe\", \"pipe\", \"pipe\"], shell: process.platform === \"win32\" });\n+  // The Windows npm shim is a .cmd file. Build the entire cmd command here,\n+  // where argument boundaries can be quoted, instead of passing an argv array\n+  // to spawn({ shell: true }), which does not escape its arguments. On POSIX,\n+  // avoid a shell altogether and pass the original argv unchanged.\n+  const windows = process.platform === \"win32\";\n+  const command = windows ? `codex ${argv.map(quoteWindowsCmdArg).join(\" \")}` : \"codex\";\n+  const child = spawn(command, windows ? [] : argv, {\n+    cwd: opts.cd,\n+    stdio: [\"pipe\", \"pipe\", \"pipe\"],\n+    shell: windows,\n+  });\n \n   let threadId = null;\n   let stdoutBuf = \"\";"
